/*
Wiring (28BYJ-48 to Arduino via ULN2003)
IN1 ->Arduino Pin 8
IN2 -> Arduino Pin 9
IN3 -> Arduino Pin 10
IN4 -> Arduino Pin 11
VCC -> 5V (external 5V supply recommended for torque)
GND -> Arduino GND
Arduino Sketch (Built-in Stepper.h)
Note on Pin Order: The Stepper library energizes coils 
sequentially.Because the 28BYJ-48 uses a 4-phase 
unipolar sequence, the pins must be
initialized in the order IN1, IN3, IN2, IN4 (pins 8, 10, 9, 11)
rather than numerical order.
*/

#include <Stepper.h>

// Number of steps per full revolution in 4-step sequence mode
const int STEPS_PER_REV = 2048;

// Initialize library with pin sequence: IN1, IN3, IN2, IN4
Stepper myStepper(STEPS_PER_REV, 8, 10, 9, 11);

void setup() {
// Set speed in RPM (typical range for 28BYJ-48 is 5 to 15 RPM)
  myStepper.setSpeed(10);
  Serial.begin(9600);
  Serial.println("Stepper motor ready.");
}

void loop() {
// Rotate 1 full revolution clockwise
  Serial.println("Rotating Clockwise...");
  myStepper.step(STEPS_PER_REV);
  delay(1000);

// Rotate 1 full revolution counter-clockwise
  Serial.println("Rotating Counter-Clockwise...");
  myStepper.step(-STEPS_PER_REV);
  delay(1000);
}
